CREATE TABLE parts(a INTEGER NOT NULL, b VARCHAR);
DESCRIBE t;
DESCRIBE parts;
DESCRIBE SELECT * FROM t;
DESCRIBE SELECT * FROM parts;
DESCRIBE SELECT a, a + 1 AS bumped, b || 'x' AS joined FROM parts;
DESC t;
